import { addCollection, type IconifyJSON } from "@iconify/svelte";
// Generated by `pnpm icons:subset`: only the icons the app uses (lucide,
// proicons, line-md). Registering the full collections shipped ~820 KB of
// icon JSON on every page, and unbundled line-md icons were fetched from
// api.iconify.design at runtime.
import iconSubset from "./subset.json";

let registered = false;

export function registerIconCollections(): void {
  if (registered) {
    return;
  }

  for (const collection of iconSubset as unknown as IconifyJSON[]) {
    addCollection(collection);
  }
  registered = true;
}
